// ============================================================
// PROCESS NOTION TASK FOR GCAL SYNC
// ============================================================
// Property mapping (Notion DB):
//   To-do (title) → GCal event summary
//   Done (checkbox) → Skip if true
//   Deadline (date) → GCal start/end time
//   Priority (select) → GCal color coding
//   GCal Event ID (rich_text) → For update vs create
//   GCal Link (url) → Store calendar link
// ============================================================

const results = [];

for (const item of $input.all()) {
  const props = item.json.properties;
  const pageId = item.json.id;

  // --- Extract fields ---
  const taskName = props['To-do']?.title?.[0]?.plain_text || 'Untitled Task';
  const isDone = props['Done']?.checkbox || false;
  const hasDate = !!props['Deadline']?.date?.start;
  const priority = props['Priority']?.select?.name || 'Medium';
  const gcalEventId = props['GCal Event ID']?.rich_text?.[0]?.plain_text || '';

  // --- Skip completed tasks ---
  if (isDone) {
    // If task is done AND has a GCal event, we could delete it
    // For now, skip
    continue;
  }

  // --- Skip tasks without a deadline ---
  if (!hasDate) {
    continue;
  }

  // --- Parse dates ---
  const startRaw = props['Deadline'].date.start;
  const endRaw = props['Deadline'].date.end;
  let startDate, endDate;

  if (startRaw.length === 10) {
    // Date only (YYYY-MM-DD) → make 1-hour block at 9 AM CT
    startDate = startRaw + 'T09:00:00-06:00';
    endDate = endRaw ? endRaw + 'T10:00:00-06:00' : startRaw + 'T10:00:00-06:00';
  } else {
    startDate = startRaw;
    if (!endRaw) {
      // No end time → add 1 hour
      const end = new Date(new Date(startRaw).getTime() + 60 * 60 * 1000);
      endDate = end.toISOString();
    } else {
      endDate = endRaw;
    }
  }

  // --- Map priority to GCal color ---
  // GCal colors: 1=Lavender, 2=Sage, 3=Grape, 4=Flamingo,
  // 5=Banana, 6=Tangerine, 7=Peacock, 8=Graphite,
  // 9=Blueberry, 10=Basil, 11=Tomato
  let colorId = '7'; // Default: Peacock (blue)
  if (priority === 'High' || priority === 'Urgent') colorId = '11'; // Tomato (red)
  else if (priority === 'Medium') colorId = '6'; // Tangerine (orange)
  else if (priority === 'Low') colorId = '2'; // Sage (green)

  results.push({
    json: {
      ...item.json,
      pageId,
      taskName,
      startDate,
      endDate,
      priority,
      colorId,
      isDone,
      gcalEventId
    }
  });
}

return results.length > 0 ? results : [];
